CREATE TABLE "finance_commissions"("id" uuid PRIMARY KEY,"created_at" timestamptz NOT NULL,"updated_at" timestamptz NOT NULL,"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"commission_no" varchar(64) NOT NULL,"idempotency_key" varchar(128) NOT NULL,"verification_id" uuid NOT NULL REFERENCES "finance_verifications"("id"),"verification_no" varchar(64) NOT NULL,"employee_id" uuid NOT NULL REFERENCES "users"("id"),"employee_name" varchar(100) NOT NULL,"status" varchar NOT NULL DEFAULT 'DRAFT',"base_currency" varchar(3) NOT NULL,"realized_revenue" numeric(28,8) NOT NULL,"allocated_cost" numeric(28,8) NOT NULL,"realized_profit" numeric(28,8) NOT NULL,"rate_percent" numeric(7,4) NOT NULL,"commission_amount" numeric(28,8) NOT NULL,"note" varchar(500),"version" bigint NOT NULL DEFAULT 1,"confirmed_at" timestamptz,"confirmed_by" uuid REFERENCES "users"("id"),"paid_at" timestamptz,"paid_by" uuid REFERENCES "users"("id"),"cancelled_at" timestamptz,"cancelled_by" uuid REFERENCES "users"("id"),"cancellation_reason" varchar(500),CONSTRAINT "commission_status_check" CHECK("status" IN('DRAFT','CONFIRMED','PAID','CANCELLED')),CONSTRAINT "commission_rate_check" CHECK("rate_percent">0 AND "rate_percent"<=100),CONSTRAINT "commission_amount_nonnegative" CHECK("commission_amount">=0));
CREATE UNIQUE INDEX "financecommission_org_no" ON "finance_commissions"("organization_id","commission_no");CREATE UNIQUE INDEX "financecommission_org_idempotency" ON "finance_commissions"("organization_id","idempotency_key");CREATE UNIQUE INDEX "financecommission_source_employee" ON "finance_commissions"("verification_id","employee_id");CREATE INDEX "financecommission_org_status_created" ON "finance_commissions"("organization_id","status","created_at");
